{
  "collections": [
    {
      "name": "articles",
      "source": "Articles",
      "id": ["id"],
      "fields": [
        {"name": "slug", "from": "slug", "type": "string"},
        {"name": "title", "from": "title", "type": "string"},
        {"name": "description", "from": "description", "type": "string"},
        {"name": "body", "from": "body", "type": "string"},
        {"name": "createdAt", "from": "createdAt", "type": "date"},
        {"name": "updatedAt", "from": "updatedAt", "type": "date"}
      ],
      "embedArrays": [
        {
          "name": "tagList",
          "fromTable": "TagList",
          "parentKey": "articleId",
          "valueColumn": "tagName",
          "maxItems": 20,
          "reason": "each article has a small bounded list of tags, read together on article endpoints"
        }
      ],
      "extendedRefs": [
        {
          "name": "author",
          "fromTable": "Users",
          "localKey": "userId",
          "copy": ["id", "username", "image"],
          "reason": "author data needed on hot article reads, so store authorId and copy username/image (rarely change)"
        }
      ],
      "counters": [
        {"name": "favoritesCount", "fromTable": "Favorites", "parentKey": "articleId", "reason": "favorites per article are unbounded; keep separate collection and denormalize a favoritesCount on Article"},
        {"name": "commentsCount", "fromTable": "Comments", "parentKey": "articleId", "reason": "comments are unbounded per article, must stay in separate collection"}
      ],
      "indexes": [
        {"keys": {"slug": 1}, "unique": true},
        {"keys": {"createdAt": 1}},
        {"keys": {"userId": 1, "createdAt": 1}},
        {"keys": {"tagList": 1}},
        {"keys": {"author.id": 1, "createdAt": 1}}
      ]
    },
    {
      "name": "comments",
      "source": "Comments",
      "id": ["id"],
      "fields": [
        {"name": "body", "from": "body", "type": "string"},
        {"name": "createdAt", "from": "createdAt", "type": "date"},
        {"name": "updatedAt", "from": "updatedAt", "type": "date"},
        {"name": "articleId", "from": "articleId", "type": "int"}
      ],
      "extendedRefs": [
        {
          "name": "author",
          "fromTable": "Users",
          "localKey": "userId",
          "copy": ["username", "image"],
          "reason": "author info shown on comment reads, copy username/image for hot reads"
        }
      ],
      "indexes": [
        {"keys": {"articleId": 1}}
      ]
    },
    {
      "name": "tags",
      "source": "Tags",
      "id": ["name"],
      "fields": [],
      "indexes": []
    },
    {
      "name": "users",
      "source": "Users",
      "id": ["id"],
      "fields": [
        {"name": "email", "from": "email", "type": "string"},
        {"name": "username", "from": "username", "type": "string"},
        {"name": "bio", "from": "bio", "type": "string"},
        {"name": "image", "from": "image", "type": "string"},
        {"name": "password", "from": "password", "type": "string"},
        {"name": "createdAt", "from": "createdAt", "type": "date"},
        {"name": "updatedAt", "from": "updatedAt", "type": "date"}
      ],
      "counters": [
        {"name": "followersCount", "fromTable": "Followers", "parentKey": "userId", "reason": "followers/following are unbounded; use a Followers collection and counters on User"},
        {"name": "followingCount", "fromTable": "Followers", "parentKey": "followerId", "reason": "followers/following are unbounded; use a Followers collection and counters on User"}
      ],
      "indexes": [
        {"keys": {"username": 1}, "unique": true},
        {"keys": {"email": 1}}
      ]
    },
    {
      "name": "favorites",
      "source": "Favorites",
      "id": ["articleId", "userId"],
      "fields": [],
      "indexes": [
        {"keys": {"articleId": 1}},
        {"keys": {"userId": 1}},
        {"keys": {"_id.articleId": 1}},
        {"keys": {"_id.userId": 1}}
      ]
    },
    {
      "name": "followers",
      "source": "Followers",
      "id": ["userId", "followerId"],
      "fields": [],
      "indexes": [
        {"keys": {"followerId": 1}},
        {"keys": {"userId": 1}},
        {"keys": {"_id.followerId": 1}},
        {"keys": {"_id.userId": 1}}
      ]
    }
  ]
}
